use super::*;

/// bsc-graph's [`ImportSpec`] as the shared renderer's — same four fields, a different crate.
pub(crate) fn to_fmt(s: &ImportSpec) -> bsc_record::imports_fmt::ImportSpec {
    bsc_record::imports_fmt::ImportSpec {
        from: s.from.clone(),
        symbols: s.symbols.clone(),
        type_only: s.type_only,
        kind: s.kind.clone(),
    }
}
